import { renderBadge } from './components/StatusBadge.js';

// ponytail: sample rows until the runs API is wired (separate ticket). The page says so on screen.
const RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];

const LABEL = { passed: 'Passed', failed: 'Failed', running: 'Running', queued: 'Queued' };
const SAMPLE_NOTE = 'Showing sample runs. Retry and New run are not connected to the deploy API yet.';

function row(r) {
  return `<tr class="is-${r.status}">
    <th scope="row" class="mono">${r.id}</th>
    <td>${r.service}</td>
    <td><span class="status is-${r.status}"><i class="glyph" aria-hidden="true"></i>${LABEL[r.status] ?? r.status}</span></td>
    <td class="num mono">${r.started}</td>
    <td class="num mono">${r.duration}</td>
    <td class="act"><button type="button" class="btn ghost retry" data-run="${r.id}" aria-label="Retry ${r.id}, ${r.service}">Retry</button></td>
  </tr>`;
}

function summary(runs) {
  const failed = runs.filter((r) => r.status === 'failed');
  if (!runs.length) return 'No runs yet';
  if (!failed.length) return runs.length === 1 ? 'Latest run passed' : `All ${runs.length} recent runs passed`;
  const f = failed[0];
  return `${failed.length} of ${runs.length} recent runs failed <span class="muted">· latest: ${f.service} <span class="mono">${f.id}</span> at <span class="mono">${f.started}</span></span>`;
}

function body(state, runs) {
  if (state === 'loading') {
    return Array.from({ length: 4 }, () => '<tr class="skeleton"><td colspan="6"><span></span></td></tr>').join('');
  }
  if (state === 'error') {
    return `<tr class="message"><td colspan="6"><span class="status is-down"><i class="glyph" aria-hidden="true"></i>Couldn't load runs.</span> Check that the deploy API is up, then reload.</td></tr>`;
  }
  if (!runs.length) {
    return `<tr class="message"><td colspan="6"><span class="status is-sample"><i class="glyph" aria-hidden="true"></i>No runs yet.</span> Start one with New run.</td></tr>`;
  }
  return runs.map(row).join('');
}

// state: 'ready' | 'loading' | 'error'. Only 'ready' is reachable until the API is wired.
export function render({ runs = RUNS, state = 'ready' } = {}) {
  document.querySelector('#app').innerHTML = `
    <header class="bar">
      <h1>pulse</h1>
      ${renderBadge()}
      <button type="button" id="new-run" class="btn primary">New run</button>
    </header>
    <main>
      <p class="answer">${state === 'ready' ? summary(runs) : 'Deploy runs'}</p>
      <p id="notice" class="notice" role="status">${SAMPLE_NOTE}</p>
      <div class="scroll" role="region" aria-label="Recent runs" tabindex="0">
        <table aria-busy="${state === 'loading'}">
          <thead><tr>
            <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
            <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
            <th scope="col"><span class="sr-only">Actions</span></th>
          </tr></thead>
          <tbody>${body(state, runs)}</tbody>
        </table>
      </div>
    </main>`;

  // The actions are not wired yet: say so where the user is looking instead of failing silently.
  const notice = document.querySelector('#notice');
  document.querySelectorAll('.retry').forEach((b) => {
    b.addEventListener('click', () => {
      notice.textContent = `Retry ${b.dataset.run} was not sent. pulse is not connected to the deploy API yet.`;
    });
  });
  document.querySelector('#new-run').addEventListener('click', () => {
    notice.textContent = 'New run was not started. pulse is not connected to the deploy API yet.';
  });
}

render();

