/* pulse tokens. OKLCH, neutrals tinted toward hue 250. See DESIGN.md. */
:root {
  --bg: oklch(0.985 0.004 250);
  --surface: oklch(1 0 0);
  --ink: oklch(0.22 0.015 250);
  --muted: oklch(0.47 0.015 250);
  --line: oklch(0.91 0.006 250);   /* decorative separators only */
  --edge: oklch(0.60 0.012 250);   /* control borders, >=3:1 */
  --accent: oklch(0.50 0.16 255);
  --on-accent: oklch(0.99 0 0);
  --ok: oklch(0.50 0.13 150);
  --bad: oklch(0.52 0.19 25);
  --warn: oklch(0.52 0.11 70);
  --bad-tint: oklch(0.52 0.19 25 / 0.06);

  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace;
  font: 400 0.875rem/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--ink);
  background: var(--bg);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: oklch(0.17 0.01 250);
    --surface: oklch(0.205 0.012 250);
    --ink: oklch(0.94 0.006 250);
    --muted: oklch(0.73 0.012 250);
    --line: oklch(0.29 0.012 250);
    --edge: oklch(0.55 0.012 250);
    --accent: oklch(0.72 0.13 255);
    --on-accent: oklch(0.17 0.01 250);
    --ok: oklch(0.76 0.14 150);
    --bad: oklch(0.71 0.17 25);
    --warn: oklch(0.80 0.12 80);
    --bad-tint: oklch(0.71 0.17 25 / 0.08);
    line-height: 1.52;
  }
}

* { box-sizing: border-box; }
body { margin: 0; }
#app { max-width: 64rem; margin-inline: auto; padding: 1rem clamp(0.75rem, 3vw, 2rem) 3rem; }

.mono { font-family: var(--mono); font-size: 0.8125rem; }
.num { text-align: end; font-variant-numeric: tabular-nums; }
.muted { color: var(--muted); font-weight: 400; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Header */
.bar { display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap; padding-block: 0.5rem 1.25rem; border-bottom: 1px solid var(--line); }
.bar h1 { margin: 0; font-size: 1.125rem; font-weight: 650; letter-spacing: -0.01em; }
.bar .btn.primary { margin-inline-start: auto; }

.answer { margin: 1.5rem 0 0.25rem; font-size: 1.25rem; font-weight: 600; text-wrap: balance; }
.notice { margin: 0 0 1rem; color: var(--muted); min-height: 1.45em; }

/* Signature: the status grammar. Every state is shape + colour + word, wherever it appears. */
.status { display: inline-flex; align-items: center; gap: 0.4rem; white-space: nowrap; font-weight: 500; }
.glyph { width: 0.625rem; height: 0.625rem; flex: none; background: currentColor; }
.is-passed .glyph, .is-live .glyph   { border-radius: 50%; }                        /* dot */
.is-failed .glyph, .is-down .glyph   { transform: rotate(45deg) scale(0.85); }       /* diamond */
.is-running .glyph                   { border-radius: 50%; background: none; border: 2px solid; }  /* ring */
.is-queued .glyph, .is-sample .glyph { border-radius: 50%; background: none; border: 1.5px dashed; } /* not live */
.status.is-passed, .status.is-live { color: var(--ok); }
.status.is-failed, .status.is-down { color: var(--bad); }
.status.is-sample, .status.is-queued { color: var(--warn); }
.status.is-running { color: var(--accent); }

.badge { padding: 0.2rem 0.6rem; border: 1px solid currentColor; border-radius: 999px; font-size: 0.8125rem; }

/* Buttons */
.btn {
  font: inherit; font-weight: 550; min-height: 2rem; padding: 0.3rem 0.85rem;
  border-radius: 6px; border: 1px solid var(--edge); background: var(--surface); color: var(--ink); cursor: pointer;
}
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }
.btn.ghost { background: transparent; }
.btn:hover { background: color-mix(in oklch, var(--ink) 7%, var(--surface)); }
.btn.primary:hover { background: color-mix(in oklch, var(--accent) 88%, var(--ink)); }
.btn:active { transform: translateY(1px); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
@media (pointer: coarse) { .btn { min-height: 2.75rem; min-width: 2.75rem; } }
@media (prefers-reduced-motion: no-preference) { .btn { transition: background-color 150ms ease-out; } }

/* Table */
.scroll { overflow-x: auto; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); }
table { width: 100%; border-collapse: collapse; min-width: 34rem; }
th, td { padding: 0.6rem 0.875rem; text-align: start; border-bottom: 1px solid var(--line); white-space: nowrap; }
thead th { font-size: 0.75rem; font-weight: 600; color: var(--muted); background: var(--bg); }
thead th.num, td.num { text-align: end; }
tbody th { font-weight: 500; }
tbody tr:last-child > * { border-bottom: 0; }
tbody tr:hover { background: color-mix(in oklch, var(--ink) 3%, var(--surface)); }
tbody tr.is-failed { background: var(--bad-tint); }
td.act { width: 1%; text-align: end; padding-block: 0.35rem; }

.message td { padding: 1.5rem 0.875rem; white-space: normal; color: var(--muted); }
.message .status { margin-inline-end: 0.35rem; }
.skeleton span { display: block; height: 0.9rem; border-radius: 4px; background: var(--line); }

