  return [4.0767416621*l-3.3077115913*m+0.2309699292*s,-1.2684380046*l+2.6097574011*m-0.3413193965*s,-0.0041960863*l-0.7034186147*m+1.7076147010*s].map(v=>Math.round(Math.min(1,Math.max(0,f(v)))*255));};
const lum=([r,g,b])=>{const c=[r,g,b].map(v=>{v/=255;return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4;});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2];};
const R=(A,B)=>{const [x,y]=[lum(A),lum(B)].sort((p,q)=>q-p);return +((x+0.05)/(y+0.05)).toFixed(2);};
const mix=(A,B,t)=>A.map((v,i)=>Math.round(v*(1-t)+B[i]*t));
const themes={
 light:{bg:o(.985,.004,250),surface:o(1,0,0),ink:o(.22,.015,250),muted:o(.47,.015,250),edge:o(.60,.012,250),accent:o(.50,.16,255),onacc:o(.99,0,0),ok:o(.50,.13,150),bad:o(.52,.19,25),warn:o(.52,.11,70),bt:.06},
 dark:{bg:o(.17,.01,250),surface:o(.205,.012,250),ink:o(.94,.006,250),muted:o(.73,.012,250),edge:o(.55,.012,250),accent:o(.72,.13,255),onacc:o(.17,.01,250),ok:o(.76,.14,150),bad:o(.71,.17,25),warn:o(.80,.12,80),bt:.08}};
for (const [name,T] of Object.entries(themes)){
 const failRow=mix(T.surface,T.bad,T.bt);
 console.log(name, {
  inkSurface:R(T.ink,T.surface),inkFailRow:R(T.ink,failRow),mutedBg:R(T.muted,T.bg),mutedSurface:R(T.muted,T.surface),
  okSurface:R(T.ok,T.surface),badFailRow:R(T.bad,failRow),warnBg:R(T.warn,T.bg),accentSurface:R(T.accent,T.surface),
  onAccent:R(T.onacc,T.accent),edgeSurface:R(T.edge,T.surface),edgeBg:R(T.edge,T.bg),ringBg:R(T.accent,T.bg)});
}
